"""Claude tool-schema extractor for actor pages."""

from __future__ import annotations

from copy import deepcopy
from datetime import UTC, datetime
from typing import Any

from agents.common.actor_classification import (
    NonActorRecord,
    classify_actor_category_type,
    load_category_catalog,
)
from agents.discovery.sources.base import FetchedDoc
from src.db.models import Actor

PROMPT_VERSION = "actor_v2"

# These columns are generated by canonical ingest or are audit/identity state,
# not facts an untrusted page may supply. Every other field comes from the model.
ACTOR_MANAGED_MODEL_FIELDS = frozenset(
    {
        "actor_id",
        "slug",
        "merged_into_actor_id",
        "source_id",
        "verification_status",
        "confidence",
        "created_at",
        "updated_at",
    }
)
ACTOR_RECORD_FIELDS = tuple(
    column.name
    for column in Actor.__table__.columns
    if column.name not in ACTOR_MANAGED_MODEL_FIELDS
)
ACTOR_CLASSIFICATION_FIELDS = (
    "actor_category",
    "category_type",
    "category_note",
    "category_needs_review",
    "classification_evidence",
)
RAW_ACTOR_FIELDS = [*ACTOR_RECORD_FIELDS, "sector_codes"]
ACTOR_FIELDS = [*RAW_ACTOR_FIELDS, *ACTOR_CLASSIFICATION_FIELDS]
ACTOR_STRING_MAX_LENGTHS = {
    column.name: int(column.type.length)
    for column in Actor.__table__.columns
    if column.name in ACTOR_RECORD_FIELDS
    and getattr(column.type, "length", None) is not None
}


class ActorRecordValidationError(ValueError):
    """An extracted actor record cannot fit the canonical actor table."""


def validate_actor_record_lengths(record: dict[str, object]) -> None:
    """Reject values that PostgreSQL would truncate at canonical write time."""
    for field_name, max_length in ACTOR_STRING_MAX_LENGTHS.items():
        value = record.get(field_name)
        if isinstance(value, str) and len(value) > max_length:
            raise ActorRecordValidationError(
                f"actor record field {field_name!r} exceeds canonical max length "
                f"{max_length} (got {len(value)})"
            )


# What each field is actually for, in the schema the model is handed.
#
# Without these, every field arrived as a bare `{"type": ["string","null"]}`
# slot: the model was told a description was a string and nothing else, and
# returned whatever the page's banner happened to say - a tagline, a navigation
# label, sometimes not a description of the organisation at all. The field
# guidance is the one lever that reliably changes extraction quality, and
# `description` matters twice over because the Phase 5 classifier reads it as
# the actor's self-description.
FIELD_GUIDANCE: dict[str, str] = {
    "name": (
        "The organisation's own full official name as the page writes it. Not a page "
        "title, not a tagline, not a programme or event name."
    ),
    "description": (
        "What this organisation IS and DOES, in 1 to 3 complete factual sentences, "
        "drawn from the page's own account of itself. Say the kind of organisation it "
        "is, the work it actually does, and who it does it for or with. "
        "Good: 'A non-profit research institute operating three field stations in the "
        "Central Valley. It runs irrigation-efficiency trials with grower cooperatives "
        "and publishes annual water-use benchmarks.' "
        "Not acceptable: a marketing tagline ('Innovating for tomorrow'), a bare "
        "category ('A university'), a navigation label, a sentence about the website, "
        "or anything the page does not state. If the page genuinely never says what "
        "the organisation does, return null rather than padding."
    ),
    "website": "The organisation's own primary site, as an absolute URL.",
    "location_city": "The city of the operating location this page is about.",
    "state": "The US state or province of that location, as the page writes it.",
    "country": "The country of that location.",
    "actor_type_raw": (
        "How the page labels the organisation in its own words, a few words at most "
        "(for example 'national laboratory', 'trade association')."
    ),
    "primary_technical_focus": (
        "The specific technical or scientific subject this organisation works on, as "
        "the page states it. A field of work, not a slogan."
    ),
    "technical_approach": (
        "How it does that work - methods, facilities, platforms or programmes the page "
        "names explicitly."
    ),
    "current_activities": (
        "Work the page says is happening now or recently: named projects, programmes, "
        "trials, services or facilities. Not aspirations or history."
    ),
    "key_constraints": (
        "Limits the page itself states - capacity, funding, regulatory or geographic. "
        "Null unless the page says so."
    ),
    "primary_lifecycle_role": (
        "A few words for where it sits in the innovation lifecycle (for example "
        "'research', 'scale-up', 'deployment'), only if the page makes that explicit."
    ),
    "funding_summary": (
        "What the page states about how it is funded: named funders, grants, awards or "
        "budget figures. Null if the page does not say."
    ),
}


def _nullable_string_schema(field_name: str) -> dict[str, object]:
    schema: dict[str, object] = {"type": ["string", "null"]}
    max_length = ACTOR_STRING_MAX_LENGTHS.get(field_name)
    if max_length is not None:
        schema["maxLength"] = max_length
    guidance = FIELD_GUIDANCE.get(field_name)
    if guidance:
        schema["description"] = guidance
    return schema

ACTOR_TOOL_SCHEMA: dict[str, Any] = {
    "type": "object",
    "additionalProperties": False,
    "properties": {
        "actors": {
            "type": "array",
            "items": {
                "type": "object",
                "additionalProperties": False,
                "properties": {
                    "name": _nullable_string_schema("name"),
                    "actor_type": _nullable_string_schema("actor_type"),
                    "actor_type_raw": _nullable_string_schema("actor_type_raw"),
                    "description": _nullable_string_schema("description"),
                    "website": _nullable_string_schema("website"),
                    "location_city": _nullable_string_schema("location_city"),
                    "state": _nullable_string_schema("state"),
                    "country": _nullable_string_schema("country"),
                    "primary_technical_focus": _nullable_string_schema(
                        "primary_technical_focus"
                    ),
                    "technical_approach": _nullable_string_schema("technical_approach"),
                    "current_activities": _nullable_string_schema("current_activities"),
                    "technology_ip_notes": _nullable_string_schema("technology_ip_notes"),
                    "key_constraints": _nullable_string_schema("key_constraints"),
                    "funding_summary": _nullable_string_schema("funding_summary"),
                    "estimated_trl": {"type": ["integer", "string", "null"]},
                    "primary_lifecycle_role": _nullable_string_schema(
                        "primary_lifecycle_role"
                    ),
                    "sector_codes": {
                        "type": ["array", "null"],
                        "items": {"type": "string"},
                    },
                },
                "required": RAW_ACTOR_FIELDS,
            },
        }
    },
    "required": ["actors"],
}


def actor_record_schema(actor_types: list[str] | tuple[str, ...]) -> dict[str, Any]:
    """Return factual actor fields; Phase 5 classification is a later ordered call.

    ``actor_types`` remains in the signature for the legacy search caller until
    the physical schema cutover, but it is intentionally not exposed to the
    extraction model.
    """
    item = deepcopy(ACTOR_TOOL_SCHEMA["properties"]["actors"]["items"])
    item["properties"] = {
        field: schema
        for field, schema in item["properties"].items()
        if field in ACTOR_RECORD_FIELDS
    }
    item["required"] = list(ACTOR_RECORD_FIELDS)
    if not any(str(value).strip() for value in actor_types):
        raise RuntimeError("actor rubric extraction requires a compatibility category enum")
    return item


class ActorExtractor:
    entity_type = "actor"
    prompt_version = PROMPT_VERSION
    json_schema = ACTOR_TOOL_SCHEMA

    def __init__(
        self,
        llm_client,
        *,
        max_tokens: int = 2048,
        classification_enabled: bool = False,
    ):
        self.llm_client = llm_client
        self.max_tokens = max_tokens
        self.classification_enabled = classification_enabled
        self.category_catalog = load_category_catalog()
        self.attention_reasons: list[str] = []

    def extract(self, doc: FetchedDoc) -> list[dict]:
        payload = self.llm_client.extract_with_tool(
            system=self._system_prompt(),
            user=self._user_prompt(doc),
            tool_name="record_actors",
            tool_description="Return organization actor records explicitly present in the source page.",
            input_schema=self.json_schema,
            max_tokens=self.max_tokens,
        )
        actors = payload.get("actors", []) if payload else []
        if not actors:
            return []
        extracted_at = datetime.now(UTC).replace(microsecond=0).isoformat()
        records: list[dict] = []
        for actor in actors:
            record = {field: actor.get(field) for field in RAW_ACTOR_FIELDS}
            if self.classification_enabled:
                try:
                    classification = classify_actor_category_type(
                        self.llm_client,
                        name=str(record.get("name") or ""),
                        self_description=str(record.get("description") or ""),
                        catalog=self.category_catalog,
                        max_tokens=min(self.max_tokens, 700),
                    )
                except NonActorRecord as exc:
                    self.attention_reasons.append(
                        f"{exc.record_kind} routed out of actor extraction: {exc.evidence}"
                    )
                    continue
                record.update(classification.as_payload())
            record["source_url"] = doc.url
            record["extracted_at"] = extracted_at
            record["prompt_version"] = self.prompt_version
            records.append(record)
        return records

    def _system_prompt(self) -> str:
        return (
            "You extract public organization records for the GHUS ecosystem database. "
            "Use only facts explicitly present in the source. Do not infer category or type, "
            "technical focus, geography, lifecycle role, TRL, or sectors. If a field is "
            "not present on the page, return null. Respect every maxLength in the tool "
            "schema. Constrained fields are short labels, not sentences; specifically, "
            "primary_lifecycle_role and actor_type_raw must be only a few words. If the "
            "page has no organizations, return an empty actors array."
        )

    def _user_prompt(self, doc: FetchedDoc) -> str:
        return (
            f"Source URL: {doc.url}\n"
            f"Content type: {doc.content_type}\n\n"
            "Extract organization actor records from this page. Any field not found in "
            "the source must be null, never guessed. Do not extract people here.\n\n"
            f"{doc.content[:12000]}"
        )
